-- ============================================================
-- AGREGAR COLUMNAS: foto y necesita_reposicion ("faltantes")
-- Pegar en Supabase → SQL Editor → Run
-- ============================================================

alter table productos add column if not exists foto text;
alter table productos add column if not exists necesita_reposicion boolean not null default false;

